INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine neue Adressversion immer 32-Bit-Adressen nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "128-Bit-Adressen"}, {"text": "Ja", "correct": false, "because": "IPv4 hat 32-Bit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresslänge hat die moderne Version?', 3, '[{"text": "128 Bit", "correct": true, "because": "Erweitert Adressraum"}, {"text": "32 Bit", "correct": false, "because": "IPv4"}, {"text": "64 Bit", "correct": false, "because": "Falsche Länge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die neue Adressversion?', 5, '[{"text": "Großer Adressraum", "correct": true, "because": "Bis zu 2^128 Adressen"}, {"text": "Autokonfiguration", "correct": true, "because": "SLAAC erleichtert"}, {"text": "Kein NAT nötig", "correct": true, "because": "Direkte Adressierung"}, {"text": "Kleinere Pakete", "correct": false, "because": "Nicht zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie unterstützt Autokonfiguration. b) Sie nutzt NAT wie die alte Version.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NAT meist überflüssig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk mit der neuen Version einrichte?', 4, '[{"text": "Adressformat", "correct": false, "because": "128-Bit wichtig"}, {"text": "Autokonfiguration", "correct": false, "because": "SLAAC hilfreich"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die neue Version rückwärtskompatibel zur alten ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Formate"}, {"text": "Ja", "correct": false, "because": "Adapter nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse dient als Loopback in der neuen Version?', 3, '[{"text": "::1", "correct": true, "because": "IPv6-Loopback"}, {"text": "127.0.0.1", "correct": false, "because": "IPv4-Loopback"}, {"text": "0.0.0.0", "correct": false, "because": "IPv4-Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die neue Adressversion?', 5, '[{"text": "Mehr Adressen", "correct": true, "because": "128-Bit vs. 32-Bit"}, {"text": "Einfachere Verwaltung", "correct": true, "because": "Autokonfiguration"}, {"text": "Kein NAT", "correct": true, "because": "Direkte Kommunikation"}, {"text": "Kleinere Header", "correct": false, "because": "Header größer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) die neue Version keine Subnetze hat und b) sie mehr Adressen bietet. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Subnetze möglich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Netzwerk mit der neuen Version einzurichten?', 4, '[{"text": "128-Bit-Adresse", "correct": false, "because": "Grundlage"}, {"text": "SLAAC", "correct": false, "because": "Autokonfiguration hilft"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ::1 für Broadcast?', 2, '[{"text": "Nein", "correct": true, "because": "Es ist Loopback"}, {"text": "Ja", "correct": false, "because": "Falsche Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken unterstützt die neue Version?', 4, '[{"text": "Autokonfiguration", "correct": true, "because": "SLAAC"}, {"text": "Multicast", "correct": true, "because": "Effiziente Gruppen"}, {"text": "NAT", "correct": false, "because": "Nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die neue Version langsamer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Leistung ähnlich"}, {"text": "Ja", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der neuen Adressversion?', 3, '[{"text": "Erweiterter Adressraum", "correct": true, "because": "Mehr Geräte"}, {"text": "Kleinere Pakete", "correct": false, "because": "Nicht zutreffend"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie hat 128-Bit-Adressen. b) Sie nutzt 32-Bit wie die alte Version.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist IPv4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist der Loopback in der neuen Version?', 4, '[{"text": "::1", "correct": true, "because": "IPv6-Loopback"}, {"text": "127.0.0.1", "correct": false, "because": "IPv4"}, {"text": "0.0.0.0", "correct": false, "because": "IPv4-Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die neue Version NAT benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Direkte Adressierung"}, {"text": "Ja", "correct": false, "because": "Überflüssig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen die neue Version nützlich?', 5, '[{"text": "Mehr Adressen", "correct": true, "because": "128-Bit"}, {"text": "Autokonfiguration", "correct": true, "because": "SLAAC"}, {"text": "Multicast", "correct": true, "because": "Effiziente Kommunikation"}, {"text": "Kleinere Header", "correct": false, "because": "Header größer"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat die neue Version Subnetze?', 3, '[{"text": "Ja", "correct": true, "because": "Subnetting möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur neuen Version?', 4, '[{"text": "Netzwerk ohne NAT", "correct": true, "because": "Direkte Adressierung"}, {"text": "32-Bit-Adressen nutzen", "correct": false, "because": "IPv4"}, {"text": "Webdesign erstellen", "correct": false, "because": "Anderer Zweck"}]');
